text:
{
  "design": {
    "theme": "splash",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar animals and body parts",
      "look_at": {
        "kind": "picture",
        "shows": "A cat and a dog with visible ears, legs and tails"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Share the lesson objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach three young animal names and shared features",
      "look_at": {
        "kind": "picture",
        "shows": "Cats, dogs and cows beside their young"
      },
      "teaches": [1, 2]
    },
    {
      "slide": 4,
      "does": "Match three young animals to their names",
      "look_at": {
        "kind": "cards",
        "shows": "A kitten, puppy and calf"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Teach lamb and chick and compare their coverings",
      "look_at": {
        "kind": "picture",
        "shows": "A sheep with a lamb and a chicken with a chick"
      },
      "teaches": [1, 2]
    },
    {
      "slide": 6,
      "does": "Check names and describe family likenesses",
      "look_at": {
        "kind": "picture",
        "shows": "Four mammal parents beside their young"
      },
      "teaches": [1, 2]
    },
    {
      "slide": 7,
      "does": "Correct the idea that a chick is a tiny adult chicken",
      "look_at": {
        "kind": "picture",
        "shows": "A chick's fluffy down beside an adult chicken's feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Teach how a chick grows into an adult",
      "look_at": {
        "kind": "picture-sequence",
        "shows": "A chick, young chicken and adult chicken"
      },
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Check understanding of a chick's covering",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 10,
      "does": "Apply growth knowledge to new photographs",
      "look_at": {
        "kind": "picture",
        "shows": "Three chicken growth stages in a mixed order"
      },
      "teaches": [3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Name these animals. Point to their ears.",
    "picture": {
      "shows": "A familiar adult cat and adult dog sitting side by side",
      "must_see": ["cat's pointed ears", "dog's floppy ears", "visible legs", "visible tails"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "compare",
      "heading": "Parents and their young",
      "columns": [
        {
          "label": "cat → kitten",
          "text": "Both have paws and whiskers.",
          "picture": {
            "shows": "An adult cat beside a kitten, both facing the camera",
            "must_see": ["adult cat", "small kitten", "visible paws", "visible whiskers"],
            "subject": "generic"
          }
        },
        {
          "label": "dog → puppy",
          "text": "Both have paws and fur.",
          "picture": {
            "shows": "An adult dog beside a puppy of the same breed",
            "must_see": ["adult dog", "small puppy", "visible paws", "fur on both"],
            "subject": "generic"
          }
        },
        {
          "label": "cow → calf",
          "text": "Both have hooves and hair.",
          "picture": {
            "shows": "An adult cow beside a calf, with their feet clearly visible",
            "must_see": ["adult cow", "small calf", "visible hooves", "short hair"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "pair",
      "heading": "Name the young",
      "instruction": "Match each picture to its name.",
      "cards": [
        {
          "label": "kitten",
          "picture": "A small kitten with visible paws and whiskers"
        },
        {
          "label": "puppy",
          "picture": "A small puppy with visible paws and fur"
        },
        {
          "label": "calf",
          "picture": "A small calf standing with visible hooves"
        }
      ]
    },
    {
      "template": "compare",
      "heading": "Two more animal families",
      "columns": [
        {
          "label": "sheep → lamb",
          "text": "Both have hooves and wool.",
          "picture": {
            "shows": "An adult sheep beside a young lamb with a visible woolly coat",
            "must_see": ["adult sheep", "young lamb", "woolly coats", "visible hooves"],
            "subject": "generic"
          }
        },
        {
          "label": "chicken → chick",
          "text": "A chick has fluffy down.",
          "picture": {
            "shows": "An adult hen with clear feathers beside a fluffy chick",
            "must_see": ["adult hen", "small chick", "hen's layered feathers", "chick's fluffy down"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Look closely",
      "questions": [
        "Name each young animal.",
        "How does the kitten look like the cat?",
        "Choose another pair. What looks the same?"
      ],
      "instruction": "Point and say.",
      "picture": {
        "shows": "Four separate photo pairs: cat and kitten, dog and puppy, cow and calf, sheep and lamb",
        "must_see": ["cat and kitten", "dog and puppy", "cow and calf", "sheep and lamb"],
        "subject": "generic"
      }
    },
    {
      "template": "visual-text",
      "heading": "Not just a tiny chicken",
      "lead": "A chick does not look just like an adult chicken.",
      "points": [
        "A chick has soft, fluffy down.",
        "An adult has larger feathers."
      ],
      "figure": {
        "shows": "Close-up views of a chick's fluffy body beside an adult hen's layered body and wing feathers",
        "must_see": ["chick's fluffy down", "hen's layered feathers", "small chick", "larger adult hen"],
        "subject": "generic"
      }
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows",
      "sequence": [
        {
          "shows": "A newly hatched chick with fluffy down, before large wing and tail feathers have grown",
          "must_see": ["small chick", "fluffy down", "short wings"],
          "subject": "generic",
          "caption": "chick"
        },
        {
          "shows": "A young chicken with growing wing and tail feathers, not yet adult-sized or fully feathered",
          "must_see": ["larger young chicken", "growing wing feathers", "short feathered tail"],
          "subject": "generic",
          "caption": "young chicken"
        },
        {
          "shows": "A fully grown adult hen with a complete feather covering and developed tail",
          "must_see": ["adult hen", "full feather covering", "developed feathered tail"],
          "subject": "generic",
          "caption": "adult chicken"
        }
      ]
    },
    {
      "template": "hinge",
      "heading": "Choose one answer",
      "stem": "What covers a newly hatched chick?",
      "options": [
        "Fur like a kitten",
        "Fluffy down",
        "Large adult feathers"
      ],
      "correct": 2
    },
    {
      "template": "big-visual",
      "heading": "Show how it grows",
      "lead": "Point to the pictures in growth order. Say what changes.",
      "figure": {
        "shows": "Three separate photographs of the same type of chicken, arranged adult hen on the left, fluffy chick in the middle and partly feathered young chicken on the right; no arrows or stage names",
        "must_see": ["fully feathered adult", "small fluffy chick", "partly feathered youngster"],
        "subject": "generic"
      }
    }
  ]
}
